//! Test helpers for a Rust client generated by [Truewire](https://truewire.dev): the Rust
//! form of `truewire.testing` (Python) and the `test/setup.ts` harness the TypeScript
//! examples use.
//!
//! - [`Mock`]: `truewire mock` for a project as a child process on free ports, with the
//!   HTTP and WebSocket URLs it announced, killed when dropped.
//! - [`http_examples`] / [`ws_examples`]: every recorded example under `spec/endpoints/`,
//!   with the function path of its endpoint, the same discovery the mock serves from.
//! - [`replay`]: run a check over every example and fail once, naming every example that
//!   failed, instead of stopping at the first.
//! - [`first_difference`]: the first JSON pointer at which two values differ.
//! - `grpc` (feature `grpc`): `GrpcMock`, an in-process fake gRPC server answering every
//!   recorded gRPC example, and `grpc_examples` to replay them (ADR 0017).
//!
//! A generated crate reaches any endpoint by its function path through `dispatch.rs`
//! (`client.call(function, request, options)` and `call_raw`), so a replay test is
//! the same few lines for every client:
//!
//! ```ignore
//! let mock = Mock::start(env!("CARGO_MANIFEST_DIR"))?;
//! let client = client_for(&mock);
//! let examples = http_examples(env!("CARGO_MANIFEST_DIR"));
//! replay(&examples, |example| {
//!     let client = &client;
//!     async move {
//!         let typed = client.call(&example.function, example.request.clone(), CallOptions::default()).await?;
//!         let raw = client.call_raw(&example.function, example.request, CallOptions::default()).await?;
//!         Ok::<_, truewire_core::Error>(Replayed::compare(typed, raw))
//!     }
//! })
//! .await
//! .assert_passed();
//! ```

mod examples;
#[cfg(feature = "grpc")]
mod grpc;
mod json;
mod mock;
mod replay;

#[cfg(feature = "grpc")]
pub use grpc::{grpc_examples, replay_grpc, GrpcExample, GrpcMock, GrpcMockError, RecordingError};

pub use examples::{http_examples, spec_dir, ws_examples, HttpExample, WsExample, WsKind};
pub use json::first_difference;
pub use mock::{Mock, MockError};
pub use replay::{replay, Labelled, Replayed, Report};
